B.EV=new A.a7("PROBLEM","\ubb38\uc81c\uc815\uc758 / \ubc30\uacbd.","\ub09c\ubc18\uc0ac \uc18c\uc7ac \uc81c\uc870 \ud604\uc7a5\uc5d0\uc11c\ub294 \uc81c\ud488 \ud45c\uba74\uc758 \uc2a4\ud06c\ub798\uce58\uc640 \ubbf8\uc138 \uacb0\ud568\uc744 \ube5b \ubc18\uc0ac \ud2b9\uc131\uc73c\ub85c \uc778\ud574 \uc721\uc548\uc73c\ub85c \uc2dd\ubcc4\ud558\uae30 \uc5b4\ub835\ub2e4. \uc791\uc5c5\uc790 \ud310\ub2e8\uc5d0 \uc758\uc874\ud558\ub294 \uc218\uc791\uc5c5 \uac80\uc0ac\ub294 \uace0\uc18d \ucee8\ubca0\uc774\uc5b4 \ub77c\uc778\uc5d0\uc11c \uc77c\uad00\uc131\uc744 \uc720\uc9c0\ud558\uae30 \uc5b4\ub835\uace0, \ubc18\ubcf5 \uc791\uc5c5\uc5d0 \ub530\ub978 \uc778\uc801 \uc624\ub958\uc640 \ud53c\ub85c \ub204\uc801\uc774 \ubd88\ub7c9 \uc720\ucd9c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uacb0\ud568 \ud0d0\uc9c0\uc640 A/B \ud488\uc9c8 \ub4f1\uae09 \ud310\uc815\uae4c\uc9c0 \uc790\ub3d9\ud654\ud558\ub294 \uc2e4\uc2dc\uac04 \uac80\uc0ac \uc2dc\uc2a4\ud15c\uc774 \ud544\uc694\ud588\ub2e4.",B.D,B.Q,null)
B.Fb=new A.a7("PROJECT","\ud504\ub85c\uc81d\ud2b8 \uc815\uc758.","VODA\ub294 \ub09c\ubc18\uc0ac \uc18c\uc7ac \uc81c\uc870 \uacf5\uc815\uc758 \uacb0\ud568 \uad00\ub9ac\uc640 \ud488\uc9c8 \ubd84\ub958\ub97c \uc790\ub3d9\ud654\ud558\ub294 AI \uae30\ubc18 \uc2a4\ub9c8\ud2b8\ud329\ud1a0\ub9ac \uc2dc\uc2a4\ud15c\uc774\ub2e4. \ucee8\ubca0\uc774\uc5b4 \ub77c\uc778\uc5d0 SNAP1(\uacb0\ud568 \ud0d0\uc9c0)\xb7SNAP2(\ud488\uc9c8 \ubd84\ub958) \ub450 \uac80\uc0ac \uad6c\uc5ed\uc744 \uc124\uacc4\ud558\uace0, Raspberry Pi\xb7Arduino \ud558\ub4dc\uc6e8\uc5b4 \uc81c\uc5b4 \u2014 YOLOv8 \uacb0\ud568 \ud0d0\uc9c0 \uc11c\ubc84 \u2014 OpenCV \ud488\uc9c8 \ubd84\ub958 \uc11c\ubc84 \u2014 Spring Boot \ubc31\uc5d4\ub4dc \u2014 Next.js \ub300\uc2dc\ubcf4\ub4dc\ub85c \uc774\uc5b4\uc9c0\ub294 End-to-End \ud480\uc2a4\ud0dd \ud30c\uc774\ud504\ub77c\uc778\uc73c\ub85c \uad6c\ud604\ud588\ub2e4.",B.D,B.Q,null)
B.Jn=s(["SNAP1 \uad6c\uc5ed: \ub4c0\uc5bc \uce74\uba54\ub77c \uc774\ubbf8\uc9c0\ub97c YOLOv8 \uc11c\ubc84\uc5d0 \uc804\ub2ec\ud574 \uc2a4\ud06c\ub798\uce58\xb7\uacb0\ud568\uc744 \uc2e4\uc2dc\uac04 \ud0d0\uc9c0\ud558\uace0 X(\ubd88\ub7c9) / GO(\ud1b5\uacfc) \ud310\uc815","SNAP2 \uad6c\uc5ed: OpenCV SimpleBlobDetector\uc640 DBSCAN \ud074\ub7ec\uc2a4\ud130\ub9c1\uc73c\ub85c Green Dot \ubd84\ud3ec\ub97c \ubd84\uc11d\ud574 A/B \ud488\uc9c8 \ub4f1\uae09 \uc790\ub3d9 \ubd84\ub958","Arduino IR \uc13c\uc11c \uac10\uc9c0 \u2192 Raspberry Pi \ucd2c\uc601\xb7\uc11c\ubc84 \ud638\ucd9c \u2192 \uacb0\uacfc \uc218\uc2e0 \u2192 \uc11c\ubcf4 \ubaa8\ud130 \ubd84\ub958 \ub3d9\uc791\uc758 \ud558\ub4dc\uc6e8\uc5b4 \uc81c\uc5b4 \ud750\ub984 \uad6c\ud604","\uacb0\ud568 \ud0d0\uc9c0 \uc11c\ubc84(FastAPI + YOLOv8)\uc640 \ud488\uc9c8 \ubd84\ub958 \uc11c\ubc84(FastAPI + OpenCV)\ub97c \ub3c5\ub9bd \uc11c\ube44\uc2a4\ub85c \ubd84\ub9ac\ud574 \uc720\uc9c0\ubcf4\uc218\uc131 \ud655\ubcf4","MongoDB\uc5d0 \ud488\uc9c8 \uc9c0\ud45c \uc800\uc7a5, GCS\uc5d0 \uc6d0\ubcf8\xb7\ubd84\uc11d \uc774\ubbf8\uc9c0 \ubcf4\uad00, Next.js \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \uc2e4\uc2dc\uac04 \ubaa8\ub2c8\ud130\ub9c1"],t.s)
B.Ff=new A.a7("SOLUTION","\ud574\uacb0\ubc29\uc548.",null,B.Jn,B.x,null)
B.K1=s(["Arduino IR \uc13c\uc11c\uac00 \uc81c\ud488\uc744 \uac10\uc9c0\ud558\uba74 Raspberry Pi\uac00 \uce74\uba54\ub77c\ub97c \ud2b8\ub9ac\uac70\ud574 \uc774\ubbf8\uc9c0\ub97c \ucd2c\uc601\ud558\uace0 GCS\uc5d0 \uc5c5\ub85c\ub4dc","SNAP1 \uacb0\ud568 \ud0d0\uc9c0 \uc11c\ubc84\uac00 YOLOv8 \ucd94\ub860\uc73c\ub85c \uacb0\ud568 \ubc14\uc6b4\ub529 \ubc15\uc2a4\ub97c \uc0dd\uc131\ud558\uace0 X(\ubd88\ub7c9) \ub610\ub294 GO(\ud1b5\uacfc) \uc2e0\ud638\ub97c \ubc18\ud658","GO \ud310\uc815 \uc81c\ud488\uc740 SNAP2\ub85c \uc774\ub3d9\ud574 OpenCV\uac00 Green Dot \uc0c9\uc0c1 \ucd94\ucd9c\xb7\uc810 \uac80\ucd9c\uc744 \uc218\ud589\ud558\uace0 DBSCAN\xb7SciPy\ub85c \uade0\uc77c\ub3c4\xb7\uad70\uc9d1\ub3c4\ub97c \ubd84\uc11d\ud574 A/B \ub4f1\uae09 \ud310\uc815","\uacb0\uacfc\ub294 Spring Boot API\ub97c \ud1b5\ud574 MongoDB\uc5d0 \uc800\uc7a5\ub418\uace0, Next.js \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \uc0dd\uc0b0\ub7c9\xb7\ubd88\ub7c9\ub960\xb7A/B \ub4f1\uae09\xb7\uade0\uc77c\ub3c4 \uc9c0\ud45c\ub97c \uc2e4\uc2dc\uac04 \uc2dc\uac01\ud654 (D3.js KDE \ud788\ud2b8\ub9f5 \ud3ec\ud568)","GCS \ubaa8\ub378 \ud30c\uc77c \ubcc0\uacbd \uac10\uc9c0\ub85c YOLO \ubaa8\ub378 \ud56b\ub9ac\ub85c\ub4dc \uad6c\uc870 \uc124\uacc4, GitHub Actions\ub85c main push \uc2dc \ube4c\ub4dc\xb7\ub3c4\ucee4 \uc774\ubbf8\uc9c0\xb7GCP VM \uc7ac\ubc30\ud3ec \uc790\ub3d9\ud654"],t.s)
